<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Services\PaymentService;
use OpenLMS\Services\SettingsService;

final class FeeController
{
    public static function index(): void
    {
        require_feature('fee_management');Auth::requireAuth();$u=Auth::user();$admin=Auth::isPrivileged();$student=in_array('student',$u['roles'],true);if(!$admin&&!$student){render_status_page(403,'Fees unavailable','Fee records are available only to students and authorized administrators.','Back to dashboard',app_url('?r=dashboard'));return;}
        $pdo=Database::connection();$error=$message=null;
        if(($_GET['payment']??'')==='success')$message='Payment verified and recorded.';elseif(($_GET['payment']??'')==='cancelled')$error='Payment was cancelled. No payment was recorded.';
        if($_SERVER['REQUEST_METHOD']==='POST'&&$admin){if(!Csrf::validate($_POST['_csrf']??null))$error='Security token expired.';else try{$action=(string)($_POST['action']??'');
            if($action==='create_invoice'){$uid=(int)($_POST['user_id']??0);$amount=round((float)($_POST['amount']??0),2);if($uid<1||$amount<=0||!in_array('student',Auth::roles($uid),true))throw new \RuntimeException('Choose a student and a positive amount.');$title=mb_substr(trim((string)($_POST['title']??'')),0,200);if($title==='')throw new \RuntimeException('Invoice title is required.');$due=self::dateOrNull((string)($_POST['due_on']??''));$notes=mb_substr(trim((string)($_POST['notes']??'')),0,3000);$now=gmdate('Y-m-d H:i:s');$currency=PaymentService::currency();$pdo->prepare("INSERT INTO fee_invoices (user_id,title,amount,due_on,status,created_at,currency,notes,updated_at) VALUES (?,?,?,?,'unpaid',?,?,?,?)")->execute([$uid,$title,$amount,$due,$now,$currency,$notes?:null,$now]);$iid=(int)$pdo->lastInsertId();notify_user($uid,'New fee invoice',$title.' · '.number_format($amount,2).' '.$currency.($due?' · Due '.$due:''),'fee',app_url('?r=fees'));Auth::audit('fees.invoice_create','Created fee invoice',null,'fee_invoice',$iid);$message='Invoice created.';}
            elseif($action==='edit_invoice'){$iid=(int)($_POST['invoice_id']??0);$invoice=PaymentService::invoice($iid);if(!$invoice)throw new \RuntimeException('Invoice not found.');$paid=(float)$invoice['paid'];$amount=round((float)($_POST['amount']??0),2);if($amount<=0||$amount+0.00001<$paid)throw new \RuntimeException('Invoice amount cannot be below payments already received.');$title=mb_substr(trim((string)($_POST['title']??'')),0,200);if($title==='')throw new \RuntimeException('Invoice title is required.');$due=self::dateOrNull((string)($_POST['due_on']??''));$notes=mb_substr(trim((string)($_POST['notes']??'')),0,3000);$status=$paid<=0?'unpaid':($paid+0.00001>=$amount?'paid':'partial');$pdo->prepare('UPDATE fee_invoices SET title=?,amount=?,due_on=?,notes=?,status=?,updated_at=? WHERE id=?')->execute([$title,$amount,$due,$notes?:null,$status,gmdate('Y-m-d H:i:s'),$iid]);Auth::audit('fees.invoice_update','Updated fee invoice',null,'fee_invoice',$iid);$message='Invoice updated.';}
            elseif($action==='delete_invoice'){$iid=(int)($_POST['invoice_id']??0);$invoice=PaymentService::invoice($iid);if(!$invoice)throw new \RuntimeException('Invoice not found.');$st=$pdo->prepare('SELECT (SELECT COUNT(*) FROM fee_payments WHERE invoice_id=?)+(SELECT COUNT(*) FROM payment_transactions WHERE invoice_id=?)');$st->execute([$iid,$iid]);if((int)$st->fetchColumn()>0)throw new \RuntimeException('Invoices with payments or payment attempts cannot be deleted. Keep them for financial history.');$pdo->prepare('DELETE FROM fee_invoices WHERE id=?')->execute([$iid]);Auth::audit('fees.invoice_delete','Deleted unused fee invoice',null,'fee_invoice',$iid);$message='Invoice deleted.';}
            elseif($action==='record_payment'){PaymentService::recordManual((int)($_POST['invoice_id']??0),(float)($_POST['amount']??0),(string)($_POST['reference']??''),(int)$u['id']);Auth::audit('fees.payment_manual','Recorded manual/cash payment');$message='Payment recorded.';}
            elseif($action==='confirm_cash'){$tx=PaymentService::confirmCash((int)($_POST['transaction_id']??0),(int)$u['id'],(string)($_POST['reference']??''));Auth::audit('fees.cash_confirm','Confirmed cash payment transaction',null,'payment_transaction',(int)$tx['id']);$message='Cash payment confirmed.';}
            elseif($action==='cancel_cash'){PaymentService::cancelCash((int)($_POST['transaction_id']??0));Auth::audit('fees.cash_cancel','Cancelled cash payment request');$message='Cash request cancelled.';}
        }catch(\Throwable $e){$error=$e instanceof \RuntimeException?$e->getMessage():'Unable to update fee records.';}}
        if($admin){$rows=$pdo->query("SELECT fi.*,u.name student_name,u.email student_email,(SELECT COALESCE(SUM(amount),0) FROM fee_payments fp WHERE fp.invoice_id=fi.id) paid FROM fee_invoices fi JOIN users u ON u.id=fi.user_id ORDER BY fi.id DESC")->fetchAll();$students=$pdo->query("SELECT DISTINCT u.id,u.name,u.email FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE r.name='student' AND u.status='active' ORDER BY u.name")->fetchAll();$txs=$pdo->query("SELECT pt.*,fi.title invoice_title,u.name student_name FROM payment_transactions pt JOIN fee_invoices fi ON fi.id=pt.invoice_id JOIN users u ON u.id=pt.user_id ORDER BY pt.id DESC LIMIT 100")->fetchAll();}
        else{$st=$pdo->prepare("SELECT fi.*,(SELECT COALESCE(SUM(amount),0) FROM fee_payments fp WHERE fp.invoice_id=fi.id) paid FROM fee_invoices fi WHERE fi.user_id=? ORDER BY CASE WHEN fi.status='paid' THEN 1 ELSE 0 END,fi.due_on,fi.id DESC");$st->execute([(int)$u['id']]);$rows=$st->fetchAll();$students=[];$st=$pdo->prepare('SELECT pt.*,fi.title invoice_title FROM payment_transactions pt JOIN fee_invoices fi ON fi.id=pt.invoice_id WHERE pt.user_id=? ORDER BY pt.id DESC LIMIT 30');$st->execute([(int)$u['id']]);$txs=$st->fetchAll();}
        foreach($rows as &$r)$r['outstanding']=max(0,round((float)$r['amount']-(float)$r['paid'],2));unset($r);
        ob_start();?><div class="page-head"><div><span class="eyebrow">Payments</span><h1>Fees</h1><p class="muted"><?= $admin?'Create, edit and reconcile student fee invoices and payment methods.':'View due invoices and pay using the methods enabled by your institution.' ?></p></div></div><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
        <?php if($admin):?><section class="card"><h2>Create invoice</h2><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="create_invoice"><label>Student<select name="user_id" required><option value="">Select student</option><?php foreach($students as $s):?><option value="<?=(int)$s['id']?>"><?=e($s['name'].' · '.$s['email'])?></option><?php endforeach;?></select></label><div class="form-row"><label>Title<input name="title" maxlength="200" required></label><label>Amount (<?=e(PaymentService::currency())?>)<input type="number" name="amount" min="0.01" step="0.01" required></label></div><label>Due date<input type="date" name="due_on"></label><label>Notes<textarea name="notes" rows="3" maxlength="3000"></textarea></label><button class="btn btn-primary">Create invoice</button></form></section><?php endif;?>
        <section class="card table-card"><h2><?= $admin?'Invoices':'My invoices' ?></h2><div class="table-scroll"><table><thead><tr><?php if($admin):?><th>Student</th><?php endif;?><th>Invoice</th><th>Amount</th><th>Paid</th><th>Due</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php if($admin):?><td><strong><?=e($r['student_name'])?></strong><small><?=e($r['student_email'])?></small></td><?php endif;?><td><strong><?=e($r['title'])?></strong><?php if(!empty($r['notes'])):?><small><?=e(mb_strimwidth((string)$r['notes'],0,100,'…'))?></small><?php endif;?></td><td><?=e(number_format((float)$r['amount'],2).' '.($r['currency']??PaymentService::currency()))?></td><td><?=e(number_format((float)$r['paid'],2))?></td><td><?=e($r['due_on']?:'—')?></td><td><span class="badge <?=$r['status']==='paid'?'badge-ok':'badge-warn'?>"><?=e($r['status'])?></span></td><td><?php if($admin):?><details><summary>Manage</summary><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="edit_invoice"><input type="hidden" name="invoice_id" value="<?=(int)$r['id']?>"><label>Title<input name="title" value="<?=e($r['title'])?>" required></label><label>Amount<input type="number" step="0.01" min="<?=e((string)max(0.01,(float)$r['paid']))?>" name="amount" value="<?=e((string)$r['amount'])?>" required></label><label>Due<input type="date" name="due_on" value="<?=e((string)$r['due_on'])?>"></label><label>Notes<textarea name="notes"><?=e((string)($r['notes']??''))?></textarea></label><button class="btn btn-small">Save</button></form><?php if((float)$r['outstanding']>0):?><form method="post"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="record_payment"><input type="hidden" name="invoice_id" value="<?=(int)$r['id']?>"><label>Record amount<input type="number" name="amount" step="0.01" min="0.01" max="<?=e((string)$r['outstanding'])?>" required></label><label>Reference<input name="reference" maxlength="190"></label><button class="btn btn-small">Record cash/manual</button></form><?php endif;?><form method="post" onsubmit="return confirm('Delete this unused invoice?')"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="delete_invoice"><input type="hidden" name="invoice_id" value="<?=(int)$r['id']?>"><button class="btn btn-small btn-danger">Delete unused invoice</button></form></details><?php elseif((float)$r['outstanding']>0):?><div class="action-row"><form method="post" action="<?=e(app_url('?r=payment-start'))?>"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="invoice_id" value="<?=(int)$r['id']?>"><?php if(PaymentService::gatewayEnabled('razorpay')):?><button class="btn btn-small" name="provider" value="razorpay">Pay with Razorpay</button><?php endif;?><?php if(PaymentService::gatewayEnabled('stripe')):?><button class="btn btn-small" name="provider" value="stripe">Pay with Stripe</button><?php endif;?><?php if(PaymentService::gatewayEnabled('cash')):?><button class="btn btn-small" name="provider" value="cash">Pay at counter</button><?php endif;?></form></div><?php else:?><span class="muted">Paid</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="muted">No fee invoices.</td></tr><?php endif;?></tbody></table></div></section>
        <?php if(!$admin&&PaymentService::gatewayEnabled('cash')):?><section class="card"><h2>Cash on counter</h2><p><?=nl2br(e((string)SettingsService::get('cash_payment_instructions','Pay at the institution counter and keep your receipt.')))?></p></section><?php endif;?>
        <?php if($admin):?><section class="card table-card"><h2>Payment transactions</h2><div class="table-scroll"><table><thead><tr><th>Student</th><th>Invoice</th><th>Provider</th><th>Amount</th><th>Status</th><th>Reference</th><th>Action</th></tr></thead><tbody><?php foreach($txs as $t):?><tr><td><?=e($t['student_name'])?></td><td><?=e($t['invoice_title'])?></td><td><?=e(ucfirst($t['provider']))?></td><td><?=e(number_format((float)$t['amount'],2).' '.$t['currency'])?></td><td><span class="badge <?=$t['status']==='paid'?'badge-ok':'badge-warn'?>"><?=e($t['status'])?></span></td><td><?=e($t['provider_payment_id']?:$t['provider_order_id']?:'—')?></td><td><?php if($t['provider']==='cash'&&$t['status']==='pending'):?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="confirm_cash"><input type="hidden" name="transaction_id" value="<?=(int)$t['id']?>"><input name="reference" maxlength="190" placeholder="Receipt/reference" required><button class="btn btn-small">Confirm</button></form><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="action" value="cancel_cash"><input type="hidden" name="transaction_id" value="<?=(int)$t['id']?>"><button class="btn btn-small">Cancel</button></form><?php else:?><span class="muted">—</span><?php endif;?></td></tr><?php endforeach;?><?php if(!$txs):?><tr><td colspan="7" class="muted">No payment transactions.</td></tr><?php endif;?></tbody></table></div></section><?php else:?><section class="card table-card"><h2>Recent payment attempts</h2><div class="table-scroll"><table><thead><tr><th>Invoice</th><th>Provider</th><th>Amount</th><th>Status</th><th>Time</th></tr></thead><tbody><?php foreach($txs as $t):?><tr><td><?=e($t['invoice_title'])?></td><td><?=e(ucfirst($t['provider']))?></td><td><?=e(number_format((float)$t['amount'],2).' '.$t['currency'])?></td><td><?=e($t['status'])?></td><td><?=e(format_app_datetime($t['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
        <?php render_page('Fees',ob_get_clean());
    }

    public static function start():void
    {
        require_feature('fee_management');Auth::requireAuth();$u=Auth::user();if(!in_array('student',$u['roles'],true)){render_status_page(403,'Payment unavailable','Only student accounts can start an online fee payment.','Back to fees',app_url('?r=fees'));return;}if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::validate($_POST['_csrf']??null)){render_status_page(400,'Invalid payment request','Refresh the fee page and try again.','Back to fees',app_url('?r=fees'));return;}$provider=(string)($_POST['provider']??'');$iid=(int)($_POST['invoice_id']??0);
        try{if($provider==='stripe'){header('Location: '.PaymentService::createStripeCheckout($iid,(int)$u['id']));exit;}if($provider==='cash'){PaymentService::createCashRequest($iid,(int)$u['id']);flash_set('success','Cash payment request created. Pay at the counter and give the receipt/reference to the administrator.');header('Location: '.app_url('?r=fees'));exit;}if($provider==='razorpay'){$order=PaymentService::createRazorpayOrder($iid,(int)$u['id']);self::razorpayPage($order);return;}throw new \RuntimeException('Choose an available payment method.');}catch(\Throwable $e){render_status_page(400,'Payment could not start',$e->getMessage(),'Back to fees',app_url('?r=fees'));}
    }

    private static function razorpayPage(array $order):void
    {
        ob_start();?><div class="auth-wrap"><section class="auth-card card"><div class="brand-mark">OL</div><h1>Razorpay payment</h1><p class="muted"><?=e($order['description'])?> · <?=e(number_format(((int)$order['amount'])/100,2).' '.$order['currency'])?></p><button class="btn btn-primary btn-block" type="button" id="razorpay-pay">Open secure checkout</button><a class="btn btn-block" href="<?=e(app_url('?r=fees'))?>">Cancel</a><form method="post" action="<?=e(app_url('?r=payment-razorpay-verify'))?>" id="razorpay-result"><input type="hidden" name="_csrf" value="<?=e(Csrf::token())?>"><input type="hidden" name="transaction_id" value="<?=(int)$order['transaction_id']?>"><input type="hidden" name="razorpay_order_id"><input type="hidden" name="razorpay_payment_id"><input type="hidden" name="razorpay_signature"></form></section></div><script src="https://checkout.razorpay.com/v1/checkout.js"></script><script>(function(){var b=document.getElementById('razorpay-pay');var f=document.getElementById('razorpay-result');var options={key:<?=json_encode($order['key_id'])?>,amount:<?=json_encode((int)$order['amount'])?>,currency:<?=json_encode($order['currency'])?>,name:'Open LMS',description:<?=json_encode($order['description'])?>,order_id:<?=json_encode($order['order_id'])?>,prefill:{name:<?=json_encode($order['name'])?>,email:<?=json_encode($order['email'])?>},handler:function(r){f.razorpay_order_id.value=r.razorpay_order_id||'';f.razorpay_payment_id.value=r.razorpay_payment_id||'';f.razorpay_signature.value=r.razorpay_signature||'';f.submit();},modal:{ondismiss:function(){location.href=<?=json_encode(app_url('?r=fees&payment=cancelled'))?>;}}};b.addEventListener('click',function(){new Razorpay(options).open();});})();</script><?php render_page('Razorpay payment',ob_get_clean(),false);
    }

    public static function razorpayVerify():void
    {
        Auth::requireAuth();$u=Auth::user();if($_SERVER['REQUEST_METHOD']!=='POST'||!Csrf::validate($_POST['_csrf']??null)){render_status_page(400,'Invalid payment response','The payment verification request is invalid.','Back to fees',app_url('?r=fees'));return;}
        try{PaymentService::verifyRazorpayPayment((int)($_POST['transaction_id']??0),(int)$u['id'],(string)($_POST['razorpay_order_id']??''),(string)($_POST['razorpay_payment_id']??''),(string)($_POST['razorpay_signature']??''));header('Location: '.app_url('?r=fees&payment=success'));exit;}catch(\Throwable $e){render_status_page(400,'Payment verification failed',$e->getMessage(),'Back to fees',app_url('?r=fees'));}
    }

    public static function stripeReturn():void
    {
        Auth::requireAuth();$u=Auth::user();try{PaymentService::verifyStripeSession((string)($_GET['session_id']??''),(int)$u['id']);header('Location: '.app_url('?r=fees&payment=success'));exit;}catch(\Throwable $e){render_status_page(400,'Stripe payment not verified',$e->getMessage(),'Back to fees',app_url('?r=fees'));}
    }

    public static function webhook():void
    {
        $provider=(string)($_GET['provider']??'');$payload=file_get_contents('php://input')?:'';$ok=false;try{if($provider==='stripe')$ok=PaymentService::handleStripeWebhook($payload,(string)($_SERVER['HTTP_STRIPE_SIGNATURE']??''));elseif($provider==='razorpay')$ok=PaymentService::handleRazorpayWebhook($payload,(string)($_SERVER['HTTP_X_RAZORPAY_SIGNATURE']??''));}catch(\Throwable $e){error_log('[OpenLMS payment webhook] '.$e->getMessage());http_response_code(400);echo 'invalid';return;}if(!$ok){http_response_code(400);echo 'invalid';return;}http_response_code(200);echo 'ok';
    }

    private static function dateOrNull(string $value):?string{$value=trim($value);if($value==='')return null;$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$value);if(!$d||$d->format('Y-m-d')!==$value)throw new \RuntimeException('Due date is invalid.');return $value;}
}
